async (intercomElement) => {
            const intercomDoc: OSKBuildingIntercomDocument = intercomElement;
            const intercomId: string = intercomElement.id;

            const unitEntryIndex = intercomDoc.intercomEntries.findIndex((entry) => entry.unitId === unitId);
            if (unitEntryIndex === -1) return; // Unit not in this intercom, skip.

            const unitEntry = intercomDoc.intercomEntries[unitEntryIndex];

            // 1. Update Call Transfer List
            const contactId = unitEntry.webRTC?.contactId;
            const callTransferListDoc = contactId
                ? await OSKBuildingIntercomCallTransferListController.default.get(buildingId, contactId)
                : undefined;

            if (callTransferListDoc) {
                const updatedCallTransferList = callTransferListDoc.callTransferList
                    .map((item) => ({
                        ...item,
                        callRecipients: item.callRecipients.filter((recipient) => recipient.callerId !== deletedUserId),
                    }))
                    .filter((item) => item.callRecipients.length > 0);

                await OSKBuildingIntercomCallTransferListController.default.update(buildingId, contactId!, {
                    callTransferList: updatedCallTransferList,
                });
            }

            // 2. Update Building Intercom Document & Sync Dénormalized User Views
            const updatedInhabitantsList: OSKIntercomUnitInhabitant[] = (unitEntry.inhabitants || []).filter(
                (i) => i.userId !== deletedUserId
            );
            const modificationDate = Timestamp.now();
            const updatedEntries = [...intercomDoc.intercomEntries];
            updatedEntries[unitEntryIndex] = {
                ...unitEntry,
                inhabitants: updatedInhabitantsList,
                displayName: unitEntry.manuallyChanged ? unitEntry.displayName : newDisplayName,
                modificationDate,
            };

            await OSKUserIntercomService.cleanUpUserIntercomsAfterInhabitantDeletion(
                intercomId,
                deletedUserId,
                updatedInhabitantsList
            );
            await OSKUserIntercomService.deleteUserIntercom(deletedUserId, intercomId);

            // 3. Publish update to ACDs (Hardware synchronization)
            await OSKIntercomMessagePublisherService.publishMessageIntercomUpdate({
                ...intercomDoc,
                intercomEntries: updatedEntries,
                modificationDate,
            });

            // 4. Save the updated master building intercom document
            return OSKBuildingIntercomController.default.update(buildingId, intercomId, {
                intercomEntries: updatedEntries,
                modificationDate,
            });
        }

