                if (options?.activateCommunicationId) {
                    const target = currentMessages.find((m) => m.communicationId === options.activateCommunicationId);
                    if (!target || target.status === 'expired') {
                        abortTransaction = true;
                        return;
                    }
                    if (target.status === 'scheduled') {
                        target.status = 'active';
                        delete target.activationTaskId;
                    }
                    // If already 'active', it's a Cloud Task Retry. We don't abort, we return it to resume hardware updates.
                    processedMessage = target;
                }

                if (options?.deactivateCommunicationId) {
                    const target = currentMessages.find((m) => m.communicationId === options.deactivateCommunicationId);
                    if (!target || target.status === 'scheduled') {
                        abortTransaction = true;
                        return;
                    }
                    if (target.status === 'active') {
                        target.status = 'expired';
                        target.schedule.endDate = new Date();
                        delete target.deactivationTaskId;
                    }
                    // If already 'expired', it's a Cloud Task Retry. Return it to resume hardware cleanup.
                    processedMessage = target;
                }

                // 1. Update existing messages or append new ones
                for (const upsertedMsg of upsertedMessages) {
                    const existingIndex = currentMessages.findIndex(
                        (m) => m.communicationId === upsertedMsg.communicationId
                    );
                    if (existingIndex > -1) {
                        currentMessages[existingIndex] = upsertedMsg;
                    } else {
                        currentMessages.push(upsertedMsg);
                    }
                }

                // 2. Preemption Logic: Only for physical displays
                if (options?.preemptActiveMessages) {
                    const nowTime = Date.now();
                    for (const msg of currentMessages) {
                        const isUpserted = upsertedMessages.some((u) => u.communicationId === msg.communicationId);
                        const isActivated = options.activateCommunicationId === msg.communicationId;

                        if (msg.status === 'active' && !isUpserted && !isActivated) {
                            msg.status = 'expired';
                            msg.schedule.endDate = new Date(nowTime); // Truncate end date to current exact time

                            if (msg.deactivationTaskId) {
                                tasksToCancel.push(msg.deactivationTaskId);
                                delete msg.deactivationTaskId;
                            }
                            if (msg.activationTaskId) {
                                tasksToCancel.push(msg.activationTaskId);
                                delete msg.activationTaskId;
                            }
                            OSKIntercomCommunicationService.default.logger.logInfo(
                                `[Task/Transaction] Preempted and expired currently active message ${msg.communicationId}.`
