                        OSKIntercomCommunicationService._getTime(m.schedule.startDate) > nowTime
                );
                const activeMessages = currentMessages.filter((m) => m.status === 'active');
                const scheduledMessages = currentMessages.filter((m) => m.status === 'scheduled');
                const expiredMessages = currentMessages.filter((m) => m.status === 'expired');

                if (futureScheduledMessages.length > OSKIntercomCommunicationService.MAX_SCHEDULED_MESSAGES) {
