                const evictedMessages = expiredMessages.slice(OSKIntercomCommunicationService.MAX_EXPIRED_MESSAGES);

                // 6. Rebuild the optimized array for the main document
                const optimizedMessagesArray = [...activeMessages, ...scheduledMessages, ...keptExpiredMessages];

                // 7. Transaction Operation: Update Main Document
